def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C' if history[0][1] == 'C' else 'D'
    if n == 2:
        return 'C'

    opp = [h[1] for h in history]
    me = [h[0] for h in history]

    def opp_defects_run(k):
        run = 0
        i = n - 1
        while i >= 0 and opp[i] == 'D' and run < k:
            run += 1
            i -= 1
        return run

    def my_defects_run(k):
        run = 0
        i = n - 1
        while i >= 0 and me[i] == 'D' and run < k:
            run += 1
            i -= 1
        return run

    if n >= 4:
        recent = opp[-4:]
        if recent.count('D') >= 3:
            if n >= 8 and opp[-8:].count('D') >= 6:
                return 'D'
            if rng.random() < 0.85:
                return 'D'
            return 'C'

    if n >= 3 and opp[-3:] == ['D', 'D', 'D']:
        return 'D'

    if n >= 2 and opp[-1] == 'D':
        if n >= 4 and opp[-4:].count('D') >= 2:
            return 'D'
        return 'D' if rng.random() < 0.7 else 'C'

    if n >= 10:
        total_opp_d = opp.count('D')
        ratio = total_opp_d / n
        if ratio > 0.45:
            if rng.random() < 0.75:
                return 'D'
            return 'C'
        if ratio < 0.08:
            return 'C'

    if n >= 6:
        last6 = opp[-6:]
        if last6.count('D') == 1:
            return 'C'
        if last6.count('D') >= 3:
            return 'D'

    if n >= 5 and opp[-5:] == ['C', 'C', 'D', 'C', 'C']:
        return 'D'

    return 'C'
